<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{CoreContractAdapter,ShipmentReadModel,FulfillmentReconciler,ReviewCoordinator,ReviewPanel};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionBatch5Test extends TestCase {
 private function fixture():array{return (require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();}
 public function testBatch5ContractsExist():void{self::assertTrue(class_exists(CoreContractAdapter::class));self::assertTrue(class_exists(ShipmentReadModel::class));self::assertTrue(class_exists(ReviewCoordinator::class));}
 public function testCoreManifestPinsRealContractsWithoutClaimingDispatch():void{$r=CoreContractAdapter::inspect();self::assertSame('509abc0ea3b6e6a6ad855dcea24228e45bce4e5e',$r['reference_sha']);self::assertFalse($r['execution_authorized']);self::assertFalse($r['native_ports_available']);self::assertContains('DigiForge\\Connector\\Printify\\MutationBridge::connect',$r['missing']);}
 public function testPinnedCorePureFulfillmentEvidenceAdapterRejectsMissingCosts():void {if(!class_exists(DigiForge\Orders\FulfillmentEvidence::class))require __DIR__.'/../fixtures/printify-connector/batch5/FulfillmentEvidence.php';self::assertIsArray(CoreContractAdapter::validateFulfillment(['method'=>'synthetic-standard'],['base_production_cost'=>10,'shipping_estimate'=>3],'USD'));self::assertInstanceOf(WP_Error::class,CoreContractAdapter::validateFulfillment(['method'=>'synthetic-standard'],[],'USD'));}
 public function testPartialSplitDuplicateAndDeliveredObservations():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$a=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);self::assertSame('PARTIAL_TRACKING_OBSERVED',$a->jsonSerialize()['state']);$ship[]=$ship[0];self::assertCount(1,ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx)->jsonSerialize()['shipments']);$ship=array_slice($ship,0,1);$ship[0]['delivered_at']=gmdate('Y-m-d H:i:sP',time()-60);$alloc[0]['items'][0]['quantity']=2;self::assertSame('DELIVERY_OBSERVED',ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx)->jsonSerialize()['state']);}
 /** @dataProvider invalidShipments */
 public function testInvalidShipmentOrLineageDenied(string $path,mixed $value):void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$r=&$ship[0];foreach(explode('.',$path)as $k)$r=&$r[$k];$r=$value;$this->expectException(InvalidArgumentException::class);ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);}
 public static function invalidShipments():array{return [['carrier','<script>'],['number',[]],['number',''],['url','javascript:alert(1)'],['line_item_ids',['wrong_line']],['delivered_at','not-date']];}
 public function testStaleOrderVersionRejected():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$ctx['expected_order_version']=2;$this->expectException(InvalidArgumentException::class);ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);}
 public function testStaleProductVersionRejected():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$ctx['product_versions']['synthetic_line_item']=2;$this->expectException(InvalidArgumentException::class);ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);}
 public function testConflictingTrackingIsVisibleAndNeverOverwrites():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$other=$ship[0];$other['delivered_at']=gmdate('Y-m-d H:i:sP',time()-60);$ship[]=$other;$r=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx)->jsonSerialize();self::assertSame('UNKNOWN',$r['state']);self::assertContains('CONFLICTING_TRACKING',$r['blockers']);self::assertTrue($r['manual_review_required']);}
 public function testCancellationAndExceptionRemainObservations():void{[$s,$o,$ship,$alloc,$ctx,$raw,$lineage]=$this->fixture();foreach(['canceled'=>'CANCELLED_ORDER_OBSERVED','has-issues'=>'EXCEPTION_REVIEW_REQUIRED']as $status=>$expected){$raw['status']=$status;$order=DigiForgePrintifyConnector\Preparation\OrderReadModel::fromProvider($s,$raw,$lineage,str_repeat('a',64));self::assertSame($expected,ShipmentReadModel::fromProvider($s,$order,$ship,$alloc,$ctx)->jsonSerialize()['state']);}}
 public function testDuplicateOlderAndConflictingSnapshotsCannotAutoApply():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$a=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);self::assertSame('DUPLICATE',FulfillmentReconciler::compare($a,$a)['disposition']);$ctx['observed_at']-=30;$b=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);self::assertSame('OUT_OF_ORDER',FulfillmentReconciler::compare($a,$b)['disposition']);$ctx['observed_at']+=30;$ship[0]['delivered_at']=gmdate('Y-m-d H:i:sP',time()-60);$c=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);self::assertSame('CONFLICT',FulfillmentReconciler::compare($a,$c)['disposition']);}
 public function testCoreReviewQueueAndLocalDecisionNeverGrantExecution():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s]=$this->fixture();$core=new SyntheticOperationsCore();$w=new ReviewCoordinator($core);$q=$w->queue($s,1);self::assertSame('PUBLICATION_PENDING',$q['items'][0]['operation_state']);$r=$w->decide($s,1,$q['items'][0],'REVIEW_LOCAL','EVIDENCE_CHECKED');self::assertSame('REVIEWED_LOCAL',$r['review_state']);self::assertFalse($r['external_execution_authorized']);self::assertInstanceOf(WP_Error::class,$w->decide($s,1,$q['items'][0],'REVIEW_LOCAL','EVIDENCE_CHECKED'));self::assertStringContainsString('local only',ReviewPanel::render($w,$s,1));}
 public function testUnknownConflictAndRevokedReviewsFailClosed():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s]=$this->fixture();foreach(['UNKNOWN','CONFLICTING']as $state){$c=new SyntheticOperationsCore();$c->operationState=$state;$w=new ReviewCoordinator($c);$item=$w->queue($s,1)['items'][0];self::assertInstanceOf(WP_Error::class,$w->decide($s,1,$item,'REVIEW_LOCAL','EVIDENCE_CHECKED'));self::assertSame($state,$w->decide($s,1,$item,'ACKNOWLEDGE','UNCERTAINTY_RETAINED')['operation_state']);}$c=new SyntheticOperationsCore();$c->fault='revoked';self::assertInstanceOf(WP_Error::class,(new ReviewCoordinator($c))->queue($s,1));self::assertInstanceOf(WP_Error::class,(new ReviewCoordinator())->queue($s,1));}
 public function testFulfillmentCoreReceiptAndRedactedExports():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$w=new ReviewCoordinator(new SyntheticOperationsCore());$model=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);self::assertSame('RECORDED',$w->observeFulfillment($s,1,$model)['disposition']);self::assertSame('DUPLICATE',$w->observeFulfillment($s,1,$model)['disposition']);$export=$w->export($s,1);self::assertIsString($export);self::assertStringNotContainsString('Private Street',$export);self::assertStringNotContainsString('TRACK123',$export);self::assertStringNotContainsString('credential',$export);}
 /** @dataProvider deniedReviewFaults */
 public function testReviewCoreFaultsCannotProduceReadyQueue(string $fault):void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$scope]=$this->fixture();$core=new SyntheticOperationsCore();$core->fault=$fault;self::assertInstanceOf(WP_Error::class,(new ReviewCoordinator($core))->queue($scope,1));}
 public static function deniedReviewFaults():array{return array_map(static fn($v)=>[$v],['revoked','wrong_shop','wrong_row_shop','incompatible','private_export','expired','stale_revision']);}
 public function testCachedVersionsAndRestoredReviewSnapshotCannotAuthorizeDecision():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$scope]=$this->fixture();foreach(['stale_product','stale_order','restored']as $fault){$core=new SyntheticOperationsCore();$w=new ReviewCoordinator($core);$item=$w->queue($scope,1)['items'][0];if($fault==='restored')$core->epoch++;else $core->fault=$fault;self::assertInstanceOf(WP_Error::class,$w->decide($scope,1,$item,'REVIEW_LOCAL','EVIDENCE_CHECKED'));}}
 public function testLocalReviewUnknownLostAcknowledgementDoesNotRearm():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s]=$this->fixture();$c=new SyntheticOperationsCore();$w=new ReviewCoordinator($c);$item=$w->queue($s,1)['items'][0];$c->fault='lost_ack';self::assertInstanceOf(WP_Error::class,$w->decide($s,1,$item,'ACKNOWLEDGE','UNCERTAINTY_RETAINED'));$c->fault='';self::assertSame('ACKNOWLEDGED',$w->queue($s,1)['items'][0]['review_state']);self::assertInstanceOf(WP_Error::class,$w->decide($s,1,$item,'ACKNOWLEDGE','UNCERTAINTY_RETAINED'));}
 public function testSplitShipmentsAndUnverifiedAllocationsRemainBounded():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$second=$ship[0];$second['number']='TRACK456';$ship[]=$second;$a=$alloc[0];$a['number']='TRACK456';$alloc[]=$a;$m=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);self::assertSame('COMPLETE_TRACKING_OBSERVED',$m->jsonSerialize()['state']);self::assertCount(2,$m->jsonSerialize()['shipments']);$unknown=ShipmentReadModel::fromProvider($s,$o,$ship,[],$ctx)->jsonSerialize();self::assertContains('SHIPMENT_QUANTITIES_UNVERIFIED',$unknown['blockers']);self::assertFalse($unknown['external_execution_authorized']);}
 public function testOverallocationAndWrongScopeRejected():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$alloc[0]['items'][0]['quantity']=3;$this->expectException(InvalidArgumentException::class);ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);}
 public function testCurrentCorePureFixtureHashesMatchPinnedEvidence():void{$m=json_decode(file_get_contents(__DIR__.'/../../docs/printify-connector/BATCH5_CORE_CONTRACT_MANIFEST.json'),true);foreach(['Validator.php','FulfillmentEvidence.php']as $file)self::assertSame($m['files']['includes/Orders/'.$file],hash_file('sha256',__DIR__.'/../fixtures/printify-connector/batch5/'.$file));}

 public function testCoreFulfillmentInspectionRequiresExactScopeAndOrderVersion():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$c=new SyntheticOperationsCore();$c->inspectionModel=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx);$identity=$c->inspectionModel->jsonSerialize()['order_identity'];$w=new ReviewCoordinator($c);self::assertInstanceOf(ShipmentReadModel::class,$w->fulfillment($s,1,$identity,1));self::assertInstanceOf(WP_Error::class,$w->fulfillment($s,1,$identity,2));$c->fault='revoked';self::assertInstanceOf(WP_Error::class,$w->fulfillment($s,1,$identity,1));}

 public function testTrackingReferencesAreNotCaseFoldedIntoOneIdentity():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$second=$ship[0];$second['number']='track123';$ship[]=$second;$a=$alloc[0];$a['number']='track123';$alloc[]=$a;$r=ShipmentReadModel::fromProvider($s,$o,$ship,$alloc,$ctx)->jsonSerialize();self::assertCount(2,$r['shipments']);self::assertSame('COMPLETE_TRACKING_OBSERVED',$r['state']);}

 public function testActualPinnedCoreSurfaceCompilesAndMissingBridgeFailsClosed():void{$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/../fixtures/printify-connector/batch5/core-surface-probe.php'],[1=>['pipe','w'],2=>['pipe','w']],$pipes);self::assertIsResource($p);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);self::assertSame(0,proc_close($p),$out.$err);$r=json_decode($out,true);self::assertSame(['DigiForge\\Connector\\Printify\\Bridge::connect','DigiForge\\Connector\\Printify\\MutationBridge::connect'],$r['missing']);self::assertFalse($r['native_ports_available']);self::assertFalse($r['wordpress_booted']);}

 public function testOrderAndFulfillmentReviewQueuesUseSameScopedCoreContract():void{require_once __DIR__.'/../fixtures/printify-connector/batch5/SyntheticOperationsCore.php';[$s]=$this->fixture();foreach(['ORDER'=>'ORDER_REVIEW','FULFILLMENT'=>'FULFILLMENT_REVIEW']as $kind=>$state){$c=new SyntheticOperationsCore();$c->kind=$kind;$c->operationState=$state;$w=new ReviewCoordinator($c);$q=$w->queue($s,1);self::assertSame($kind,$q['items'][0]['kind']);self::assertSame('REVIEWED_LOCAL',$w->decide($s,1,$q['items'][0],'REVIEW_LOCAL','EVIDENCE_CHECKED')['review_state']);}}

 public function testShipmentObservationCannotUseAnotherShopScope():void{[$s,$o,$ship,$alloc,$ctx]=$this->fixture();$other=new DigiForge\Connector\Printify\ShopBinding(3,'standard_pod',99003,'99004','test',7,new DigiForge\Connector\Printify\CredentialReference(99003),str_repeat('b',64),2000000000);$this->expectException(InvalidArgumentException::class);ShipmentReadModel::fromProvider($other,$o,$ship,$alloc,$ctx);}

}
